components.css:
.ds-btn-icon-ghost { display: inline-flex; align-items: center; justify-content: center; width: 1.75rem; height: 1.75rem; padding: 0; border-radius: 0.5rem; border: 1px solid transparent; background: transparent; color: #8b92a0; cursor: pointer; font-family: 'JetBrains Mono Variable', monospace; transition: background 150ms ease, color 150ms ease; outline: none; flex-shrink: 0; }
.ds-btn-icon-ghost:hover { background: rgba(255,255,255,0.05); color: #e8e6e1; }
.ds-btn-icon-ghost:focus-visible { box-shadow: 0 0 0 2px rgba(139,146,160,0.5); }

.ds-region-row { display: flex; align-items: stretch; border-top: 1px solid #2a2f3a; padding: 6px 0; font-family: 'JetBrains Mono Variable', monospace; }
.ds-region-row:first-child { border-top: none; }
.ds-region-row__grip { display: flex; width: 1.25rem; flex-shrink: 0; align-items: center; justify-content: center; cursor: grab; color: #8b92a0; opacity: 0; transition: opacity 150ms ease; background: transparent; border: none; padding: 0; }
.ds-region-row:hover .ds-region-row__grip { opacity: 0.6; }
.ds-region-row__label { display: flex; flex-direction: column; justify-content: center; gap: 2px; flex: 1; min-width: 5rem; overflow: hidden; padding-right: 6px; }
.ds-region-row__name { font-size: 0.8125rem; font-weight: 600; color: #e8e6e1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-region-row__tz { font-size: 0.6875rem; color: #8b92a0; }
.ds-region-row__time { display: flex; align-items: center; width: 7rem; flex-shrink: 0; font-size: 1.125rem; font-weight: 500; font-family: 'JetBrains Mono Variable', monospace; }
.ds-region-row__time--ok { color: #4ade80; }
.ds-region-row__time--mild { color: #fbbf24; }
.ds-region-row__time--heavy { color: #f87171; }
.ds-region-row__track { flex: 1; height: 3rem; background: #2a2f3a; border-radius: 2px; }
.ds-region-row__remove { display: flex; align-items: center; justify-content: center; width: 2.75rem; height: 100%; flex-shrink: 0; opacity: 0; transition: opacity 150ms ease; background: transparent; border: none; color: #8b92a0; cursor: pointer; }
.ds-region-row:hover .ds-region-row__remove { opacity: 1; }

.ds-cell { flex: 1; height: 3rem; border: none; padding: 0; cursor: pointer; }
.ds-cell--ok { background: #4fa98c; }
.ds-cell--ok-pastel { background: color-mix(in srgb, #4fa98c, white 30%); }
.ds-cell--mild { background: #d9a052; }
.ds-cell--mild-pastel { background: color-mix(in srgb, #d9a052, white 30%); }
.ds-cell--heavy { background: #c4573f; }
.ds-cell--heavy-pastel { background: color-mix(in srgb, #c4573f, white 30%); }
